script:
if (-not $USERNAME) { $USERNAME = 'ldapbind' }
if (-not $PASSWORD) { $PASSWORD = 'Ldap-Bind2026!' }
if (-not (Get-LocalUser -Name $USERNAME -ErrorAction Ignore)) {
    New-LocalUser -Name $USERNAME `
        -Password (ConvertTo-SecureString $PASSWORD -AsPlainText -Force) `
        -PasswordNeverExpires -AccountNeverExpires `
        -Description 'LDAP bind / monitoring account - do not disable' | Out-Null
} else {
    Set-LocalUser -Name $USERNAME -PasswordNeverExpires:$true -AccountNeverExpires:$true
}
if ($ADD_GROUP) {
    $members = net localgroup $ADD_GROUP 2>$null | Out-String
    if ($members -notmatch [regex]::Escape($USERNAME)) { net localgroup $ADD_GROUP $USERNAME /add | Out-Null }
}
